contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will call addReward (owner only) and then notifyRewardAmount via rewardDistributor.
    // To call owner-only functions we rely on the fresh deployment: the test contract is the deployer of C
    // per the harness description, so InvMutTest is the owner of c. We'll set rewardDistributor to this contract
    // or to another address passed in. To satisfy the external call requirement (notifyRewardAmount requires
    // msg.sender == rewardDistributor) we pass the distributor address as a parameter and ensure it matches.

    function run(address rewardToken, address distributor, uint256 amount) public payable {
        require(rewardToken != address(0));
        // Precondition: amount > 0 to satisfy notifyRewardAmount's require
        require(amount > 0);

        // Ensure this contract is owner: owner() should equal address(this) because the harness deploys c with this contract as deployer
        // (If that's not the case the subsequent owner-only calls would revert; we don't catch that here.)

        // 1) add reward token as owner
        c.addReward(rewardToken);

        // 2) set rewardDistributor to the provided distributor address (owner only)
        c.setRewardDistributor(distributor);

        // Read observables before notify: totalSupply and reward periodFinish
        uint256 beforeTotal = c.totalSupply();
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);

        // 3) Make sure this contract has approved distributor to transfer rewardToken if distributor == address(this)
        // We cannot mint tokens here; instead, we only call notifyRewardAmount as if the distributor is this contract.
        // The notifyRewardAmount will attempt safeTransferFrom(distributor -> c). That call will fail unless the distributor
        // actually has and approved tokens. To make the call reachable for the prover, we instead choose to call
        // notifyRewardAmount from the distributor parameter by invoking via low-level call when distributor == address(this).
        // However low-level calls would not change msg.sender for c; therefore the only way to satisfy msg.sender == rewardDistributor
        // is to have distributor equal address(this) and the test contract must be able to perform safeTransferFrom of the rewardToken.
        // The harness deploys c fresh but does not ensure token balance. To make the property meaningful and provable even if transferFrom reverts,
        // we capture whether notifyRewardAmount reverted and then assert the invariant only in the non-reverted case.

        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observables after attempt
        uint256 afterTotal = c.totalSupply();
        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);

        // General rule: If notifyRewardAmount did not revert, then totalSupply is unchanged and periodFinish is at least now (i.e., >= beforeFinish and >= block.timestamp - but we only can compare to beforeFinish and ensure non-decrease), and afterFinish >= beforeFinish.
        // Also assert that if call succeeded then afterTotal == beforeTotal.
        assert(reverted || (afterTotal == beforeTotal && afterFinish >= beforeFinish));
    }

    receive() external payable {}
}

