        } catch {
            setDist = false;
        }

        // Read observables before attempting notifyRewardAmount
        uint256 beforeTotal = c.totalSupply();
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);

        // Attempt notifyRewardAmount; capture whether it reverted.
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
