        } catch {
            reverted = true;
        }

        // Read observables after attempt
        uint256 afterTotal = c.totalSupply();
        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);

        // General rule: If notifyRewardAmount did not revert then totalSupply is unchanged and periodFinish did not decrease.
        // We allow the helper owner/distributor calls to have failed; the assertion is conditional on notifyRewardAmount success.
