contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry
    function run(address rewardToken, uint256 amount, address distributor) public payable {
        require(amount > 0, "amount>0");
        // initial setup: owner must have set rewardDistributor to 'distributor' and added rewardToken
        // We cannot call owner-only functions here because msg.sender is this contract; instead
        // rely on the checker deploying c freshly and then we simulate the allowed external calls.
        // Ensure this contract has enough of rewardToken to transfer if needed for the successful path.

        // Read prior values
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 beforeBal = IERC20(rewardToken).balanceOf(address(c));

        // Attempt notifyRewardAmount as distributor by calling via a delegate call pattern is not possible here.
        // We must call notifyRewardAmount from msg.sender == rewardDistributor. We can try both behaviors:
        bool reverted;
        // first try as non-distributor (likely revert)
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterBal = IERC20(rewardToken).balanceOf(address(c));

        // General rule: If notifyRewardAmount did not revert then periodFinish was advanced to block.timestamp + DURATION and contract balance increased by amount; 
        // If it reverted then either periodFinish unchanged or balance unchanged (no partial transfer).
        // Express as: (not reverted) -> (afterFinish >= beforeFinish && afterBal == beforeBal + amount)
        // and (reverted) -> (afterBal == beforeBal && afterFinish == beforeFinish)
        // Combine into single assert using implication pattern: (A?B:C) style is not available, so use logical equivalences.

        // We cannot use block.timestamp in assert since it's allowed, but to avoid dependence we'll only assert the relationships above.
        assert((!reverted && afterBal == beforeBal + amount && afterFinish >= beforeFinish) || (reverted && afterBal == beforeBal && afterFinish == beforeFinish));
    }

    receive() external payable {}
}

