contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: distributor must be address paying rewards; rewardToken must have been added by owner beforehand.
    // We require that this contract is the rewardDistributor when calling notifyRewardAmount.
    function run(address rewardToken, address distributor, uint256 amount) public payable {
        require(amount > 0, "amount must be >0 for meaningful rule");

        // Ensure this test contract is the distributor expected by c by calling setRewardDistributor as owner.
        // The deployer of c is the InvMutTest contract (per harness), so this contract is owner and can set distributor.
        c.setRewardDistributor(distributor);

        // Add reward token (only owner) if not already added. If already added, addReward will revert; catch that.
        bool added;
        try c.addReward(rewardToken) {
            added = true;
        } catch {
            added = false;
        }

        // Transfer required tokens to the distributor (must be msg.sender==this contract to call ERC20 approvals/transfers is impossible here),
        // so instead we rely on the general rule about notifyRewardAmount behavior: when notifyRewardAmount is invoked by the configured distributor
        // with amount>0 on a known reward token, it should set periodFinish >= block.timestamp and not leave rewardRate zero.

        // Call notifyRewardAmount as distributor. Since the harness will call run once and msg.sender for calls from this contract
        // is this contract, we simulate the distributor by calling setRewardDistributor to be this contract and then invoking notifyRewardAmount.
        // For generality we attempt both: if distributor == address(this) then we call directly; otherwise we attempt call and capture revert.

        bool reverted;
        // To satisfy the constraint that calls that mutate c must be top-level statements, perform the call directly and catch revert.
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable values
        uint40 finish = c.rewardPeriodFinish(rewardToken);

        // The general property: if the call did not revert, then finish >= block.timestamp and the period finish is nonzero.
        // If the call reverted, then either msg.sender was not rewardDistributor or amount==0 or token unknown. We assert that in that case
        // at least one of those public-observable conditions holds: msg.sender != rewardDistributor OR amount==0 OR rewardToken unknown.
        // We can check rewardDistributor address and whether the token was known by checking rewardPeriodFinish != 0 as addReward sets it to block.timestamp.

        address configured = c.rewardDistributor();

        // Compose the assertion: either the notify call reverted and (configured != address(this) || amount == 0 || finish == 0),
        // or it did not revert and finish >= block.timestamp.
        assert(
            reverted && (configured != address(this) || amount == 0 || finish == 0) || (!reverted && finish >= block.timestamp)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We call notifyRewardAmount for a rewardToken with amount. The call may revert or succeed.
    function run(address rewardToken, uint256 amount) public payable {
        require(address(c) != address(0));

        // Try calling notifyRewardAmount and record whether it reverted.
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observables: configured distributor and stored period finish for the token.
        address configured = c.rewardDistributor();
        uint40 finish = c.rewardPeriodFinish(rewardToken);

        // If the call did not revert, then finish must be at least the current block.timestamp.
        // If it reverted, then at least one of: caller != configured distributor OR amount == 0 OR token unknown (finish == 0).
        assert((!reverted && finish >= block.timestamp) || (reverted && (configured != address(this) || amount == 0 || finish == 0)));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We call notifyRewardAmount as the (test) caller. The test assumes the caller is set as rewardDistributor beforehand by the contract owner.
    // Parameters:
    // - rewardToken: an existing reward token previously added via addReward
    // - amount: amount to notify (we require > 0)
    function run(address rewardToken, uint256 amount) public payable {
        require(amount > 0);
        // Observables before the call
        address configured = c.rewardDistributor();
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 beforeBal = address(c).balance;

        // Attempt the call and capture whether it reverted
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterBal = address(c).balance;

        // If the caller equals the configured distributor and the token was known (beforeFinish != 0), the call must not revert,
        // and afterFinish must be >= block.timestamp and contract balance increased by amount.
        // Otherwise, if it did revert, nothing is required beyond that fact (we allow revert for other reasons).
        assert((!reverted && configured == address(this) && beforeFinish != 0 && afterFinish >= block.timestamp && afterBal >= beforeBal + amount) || (reverted && (configured != address(this) || beforeFinish == 0)));
    }

    receive() external payable {}
}

