    // We call notifyRewardAmount as msg.sender == address(this).
    // Params:
    // - rewardToken: token address that may or may not have been added earlier via addReward by the owner
    // - amount: amount to notify and transfer
    function run(address rewardToken, uint256 amount) public payable {
        // allow any inputs; amount==0 is a triggering condition for revert in contract
        // Observe pre-call distributor and rewardPeriodFinish and balance
        address configured = c.rewardDistributor();
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 beforeBal = address(c).balance;

        bool reverted;
        // Attempt the call and capture whether it reverted
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterBal = address(c).balance;

        // If caller is configured distributor, token was known (beforeFinish != 0), and amount>0,
        // then the call must have succeeded (not reverted), the contract balance must increase by exactly amount,
        // and the periodFinish for the token must be >= block.timestamp.
        // Otherwise the call must have reverted (e.g., not distributor, unknown token, or amount==0).
        assert(
            (configured == address(this) && beforeFinish != 0 && amount > 0 && !reverted && afterBal == beforeBal + amount && afterFinish >= block.timestamp)
            ||
            (reverted && (configured != address(this) || beforeFinish == 0 || amount == 0))
        );
