contract InvMutTest {
    C c;
    IERC20 token;

    constructor(C _c) {
        c = _c;
        token = c.stakingToken();
    }

    // params: from account (msg.sender for token ops will be this contract), amount to stake
    function run(uint256 approveAmount, uint256 stakeAmount) public payable {
        require(approveAmount >= stakeAmount, "approve must cover stake");

        // Ensure this test contract has enough staking token balance to transferFrom: caller of stakeFor is msg.sender of c.stakeFor
        // The checker deploys c and sets msg.sender for c calls to this contract. We must not assume token minting, but we can only interact via public surface.
        // We attempt to approve c to pull tokens; if transferFrom fails then stake will revert and we capture that.

        // Approve c to spend tokens from this contract
        bool stakeReverted;
        // read before values
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));
        uint256 contractTokenBalBefore = token.balanceOf(address(c));

        // Approve the staking token for c
        token.approve(address(c), approveAmount);

        // Try to stake via stakeFor (public) by calling stakeFor on c where msg.sender is this contract
        try c.stakeFor(address(this), stakeAmount) {
            stakeReverted = false;
        } catch {
            stakeReverted = true;
        }

        // read after values
        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));
        uint256 contractTokenBalAfter = token.balanceOf(address(c));

        // General rule: if stake did not revert then totalSupply and user balance increased by exactly stakeAmount
        // and the token balance held by c increased by at least stakeAmount (some tokens could have been present before).
        // If stake reverted then none of these on-chain c values changed.
        assert(
            stakeReverted
            ? (totalAfter == totalBefore && balAfter == balBefore && contractTokenBalAfter == contractTokenBalBefore)
            : (totalAfter == totalBefore + stakeAmount && balAfter == balBefore + stakeAmount && contractTokenBalAfter >= contractTokenBalBefore + stakeAmount - 0)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // distributor: address to set as rewardDistributor (must be set by owner),
    // rewardToken: a token address that has been added via addReward by the owner,
    // amount: amount to notify (must be >0 to pass require in notifyRewardAmount)
    function run(address distributor, address rewardToken, uint256 amount) public payable {
        // no preconditions on params

        // read initial observable state
        uint40 periodFinishBefore = c.rewardPeriodFinish(rewardToken);
        uint256 totalBefore = c.totalSupply();
        address distributorBefore = c.rewardDistributor();

        // set reward distributor as owner (contract deployer is owner). This is a state-changing call and must be top-level.
        c.setRewardDistributor(distributor);

        // call notifyRewardAmount as msg.sender = this contract; must be top-level and may revert
        bool notified;
        try c.notifyRewardAmount(rewardToken, amount) {
            notified = true;
        } catch {
            notified = false;
        }

        // read after values
        uint40 periodFinishAfter = c.rewardPeriodFinish(rewardToken);
        uint256 totalAfter = c.totalSupply();
        address distributorAfter = c.rewardDistributor();

        // General rule:
        // - calling setRewardDistributor updates rewardDistributor observable value to the provided address
        // - if notifyRewardAmount succeeded (notified == true) then periodFinishAfter > block.timestamp and periodFinishAfter > periodFinishBefore
        // - if notifyRewardAmount reverted then totalSupply and periodFinish did not increase and rewardDistributor remains the set value
        assert(
            // distributor was updated by setRewardDistributor
            distributorAfter == distributor
            && (
                notified
