    // params:
    // staker: address that will be used as the caller for stakeFor and withdraw (since this contract is the caller to c, we use this contract as msg.sender for c calls)
    // stakeAmount: amount to stake first (must be > 0)
    // withdrawAmount: amount to withdraw (>= 0)
    // claim: whether to claim rewards on withdraw
    function run(uint256 stakeAmount, uint256 withdrawAmount, bool claim) public payable {
        require(stakeAmount > 0);

        // prepare approvals and balances: the test contract must have tokens to stake
        // We cannot mint tokens here; assume the token allows transferFrom from this contract if balance/allowance suffice in the environment.
        // Observe pre-state
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(address(this));
        uint256 beforeContractTokenBalance = token.balanceOf(address(c));

        // perform stakeFor by calling stakeFor(address,uint256) via c.stakeFor (top-level state-changing call)
        // This call may revert (e.g., if token allowance/balance insufficient). Capture revert.
        bool stakeReverted;
        try c.stakeFor(address(this), stakeAmount) {
            stakeReverted = false;
        } catch {
            stakeReverted = true;
        }

        // If stake succeeded, read post-stake observed values
        uint256 afterTotalStake;
        uint256 afterBalanceStake;
        uint256 afterContractTokenBalanceStake;
        if (!stakeReverted) {
            afterTotalStake = c.totalSupply();
            afterBalanceStake = c.balanceOf(address(this));
            afterContractTokenBalanceStake = token.balanceOf(address(c));
        } else {
            // set to before values to allow a uniform assertion later
            afterTotalStake = beforeTotal;
            afterBalanceStake = beforeBalance;
            afterContractTokenBalanceStake = beforeContractTokenBalance;
        }

        // Now attempt withdraw(withdrawAmount, claim)
        // Must be a top-level call; capture revert flag and observe post-state when it succeeds
        bool withdrawReverted;
        try c.withdraw(withdrawAmount, claim) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        uint256 finalTotal = c.totalSupply();
        uint256 finalBalance = c.balanceOf(address(this));
        uint256 finalContractTokenBalance = token.balanceOf(address(c));

        // General rule asserted:
        // If stake succeeded and withdraw succeeded then:
        //  - the staker's c.balance decreased by exactly withdrawAmount (cannot underflow by requirement in contract)
        //  - totalSupply decreased by exactly withdrawAmount
        //  - the contract's stakingToken balance decreased by exactly withdrawAmount
        // If stake reverted then withdraw cannot have succeeded in reducing balances (withdraw would likely revert due to insufficient balance) — we allow either withdraw reverted or no change.
        // We express a single assertion covering both cases.
        assert(
            // Case: both stake and withdraw succeeded
            (!stakeReverted && !withdrawReverted && finalBalance + withdrawAmount == afterBalanceStake && finalTotal + withdrawAmount == afterTotalStake && finalContractTokenBalance + withdrawAmount == afterContractTokenBalanceStake)
            // Case: stake succeeded but withdraw reverted -> balances remain as afterStake
            || (!stakeReverted && withdrawReverted && finalBalance == afterBalanceStake && finalTotal == afterTotalStake && finalContractTokenBalance == afterContractTokenBalanceStake)
            // Case: stake reverted -> nothing changed from before (withdraw may or may not have reverted, but if withdraw succeeded it cannot reduce below before values; be permissive: either final equals before or withdraw reverted)
            || (stakeReverted && ( (withdrawReverted && finalBalance == beforeBalance && finalTotal == beforeTotal && finalContractTokenBalance == beforeContractTokenBalance) || (!withdrawReverted && finalBalance + withdrawAmount == beforeBalance && finalTotal + withdrawAmount == beforeTotal && finalContractTokenBalance + withdrawAmount == beforeContractTokenBalance) ))
        );
    }

    receive() external payable {}
}

