contract InvMutTest {
    C c;
    IERC20 token;

    constructor(C _c) {
        c = _c;
        token = c.stakingToken();
    }

    // We will call stakeFor(from, amount) by having this contract approve and then
    // having this contract call c.stakeFor(...) which uses msg.sender to pull tokens.
    // To allow c to pull tokens, we need to transfer tokens to this contract beforehand.
    // The test takes as parameters the recipient to credit and an amount to stake.
    // It asserts the general invariant: if stakeFor does not revert then totalSupply and
    // balanceOf(recipient) increase exactly by amount, and if amount==0 stakeFor reverts.

    function run(address recipient, uint256 amount) public payable {
        require(address(token) != address(0));

        // Record before values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBal = c.balanceOf(recipient);

        // Try to ensure this contract has `amount` tokens to transfer to c when stakeFor is called.
        // We cannot mint tokens; we can only use the observable ERC20 interface. To avoid making
        // assumptions about token supply, we branch on amount == 0: if amount > 0 we first
        // try to transfer `amount` tokens from msg.sender (the caller of run) to this contract
        // so that this contract can then call c.stakeFor and the stakingToken.safeTransferFrom will succeed.
        // The test runner will provide allowances/transfers as needed for some executions; if transfers fail,
        // stakeFor will likely revert and we capture that.

        bool transferredToThis = false;
        if (amount > 0) {
            // Attempt to pull tokens from the externally-owned caller into this contract.
            // This call may revert; we catch that by using low-level call on the token contract.
            // We use the ERC20 transferFrom selector: transferFrom(msg.sender, address(this), amount)
            (bool ok, bytes memory ret) = address(token).call(
                abi.encodeWithSelector(token.transferFrom.selector, msg.sender, address(this), amount)
            );
            // treat success only if call returned true or empty (some tokens return bool, some return nothing)
            if (ok && (ret.length == 0 || abi.decode(ret, (bool)))) {
                transferredToThis = true;
            }
            // Also try to approve c to pull tokens from this contract: approve(address(this) is not needed,
            // c.stakeFor will call stakingToken.safeTransferFrom(msg.sender, address(this), _amount) where msg.sender is this contract,
            // so c will attempt transferFrom(this contract, c, amount) and thus this contract must have approved c beforehand.
            // Approve c to spend from this contract.
            address stakingAddr = address(c.stakingToken());
            // approve c to spend amount from this contract
            address(token).call(abi.encodeWithSelector(token.approve.selector, address(c), amount));
        }

        // Now perform the stakeFor call and capture whether it reverted.
        bool reverted;
        try c.stakeFor(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterBal = c.balanceOf(recipient);

