contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that will be used for property testing
    function run(address staker, uint256 stakeAmount, uint256 withdrawAmount, bool claim) public payable {
        require(staker != address(0), "nonzero staker");
        // Ensure we start from a known situation by adding staking tokens via stakeFor if stakeAmount>0
        // Note: stakeFor pulls tokens from msg.sender, which is this contract. So we cannot actually transfer tokens
        // into c unless the staking token has been pre-approved and this contract holds tokens. We avoid requiring that.
        // Instead, we only observe public getters before and after a withdraw call, and call withdraw from the staker
        // by invoking c.withdraw as if this contract is that staker — the test harness sets msg.sender appropriately.

        // Read before-values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(staker);
        uint256 contractBalBefore = address(c).balance;

        // We will attempt to invoke withdraw from the staker. Since this contract is the caller of c in the harness,
        // we treat `staker` as the target of observation, but we must call withdraw as that staker — the harness
        // environment makes this contract the msg.sender for calls, so to simulate calling from staker we instead
        // only call withdraw if staker equals address(this). If not, we still call withdraw to cover general behavior.
        // We must ensure the call is a top-level statement.

        bool reverted;
        try c.withdraw(withdrawAmount, claim) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint256 afterTotal = c.totalSupply();
        uint256 afterBalance = c.balanceOf(staker);
        uint256 contractBalAfter = address(c).balance;

        // General invariant to assert:
        // - The staker's balance must not increase as a result of withdraw (cannot gain stake by withdrawing)
        // - The total supply must not increase as a result of withdraw
        // - If call did not revert, then totalSupply decreased by at most withdrawAmount and contract balance did not increase by more than 0
        // We combine into a single assertion formula that must hold for all inputs.

        // Formulated as: afterBalance <= beforeBalance AND afterTotal <= beforeTotal AND
        // (reverted OR (beforeTotal - afterTotal <= withdrawAmount && contractBalAfter <= contractBalBefore + 0))
        // Note: the contract balance check ensures withdraw does not magically create Ether in c. We express +0 explicitly.

        assert(
            afterBalance <= beforeBalance
            && afterTotal <= beforeTotal
            && (reverted || (beforeTotal - afterTotal <= withdrawAmount && contractBalAfter <= contractBalBefore))
        );
    }

    // accept ether if needed by called functions
    receive() external payable {}
}

