    // by the harness; stakingToken is set in its constructor. InvMutTest will call stakeFor
    // which invokes stakingToken.transferFrom. To allow transferFrom to succeed, the test
    // uses the fact that msg.sender for calls from this contract is this contract itself.
    // The test assumes the staking token held by this contract can be transferred from this
    // contract to c. We therefore take as parameters an address `from` (ignored) and `amount`.

    // We don't hardcode token interactions here; instead we require amount>0 and that this
    // contract currently has at least `amount` of stakingToken via the public stakingToken
    // getter and balanceOf. We then approve c to pull tokens and call stakeFor. The rule
    // asserts that if stakeFor does not revert then totalSupply and balanceOf(_for) increased
    // by exactly amount.

    function run(address forAddress, uint256 amount) public payable {
        require(amount > 0, "need positive amount");

        // Observe staking token
        address stakingAddr = address(c.stakingToken());
        // Ensure this contract has sufficient token balance to stake
        uint256 myBal = IERC20(stakingAddr).balanceOf(address(this));
        require(myBal >= amount, "insufficient tokens in test contract");

        // Record before values
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(forAddress);

        // Approve c to pull tokens from this contract
        bool approveOk = IERC20(stakingAddr).approve(address(c), amount);
        require(approveOk, "approve failed");

        // Call stakeFor: from this contract (msg.sender = this) supplying tokens
        bool reverted;
        try c.stakeFor(forAddress, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values (always via public getters)
        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(forAddress);

        // If the call reverted, then nothing in c's state must have changed.
        // If it did not revert, ensure totalSupply and balanceOf increased by exactly amount.
        assert(
            reverted
            ? (totalAfter == totalBefore && balAfter == balBefore)
            : (totalAfter == totalBefore + amount && balAfter == balBefore + amount)
