    // It requires this test contract to hold at least _amount of the staking token so transferFrom can succeed.
    // The asserted invariant: if the call reverts, c.totalSupply() and c.balanceOf(_for) remain as before;
    // otherwise they increase by exactly _amount.

    function run(address _for, uint256 _amount) public payable {
        require(_for != address(0), "invalid for");
        // allow zero amount to be tested as well, but stakeFor requires >0 so it will revert in that case

