contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test withdraw behavior from this contract (msg.sender for c calls will be this contract)
    // Params: amount to withdraw and whether to claim rewards; this contract must hold and approve tokens if staking is needed.
    function run(uint256 amount, bool claim) public payable {
        // Observe staking token address via c's public getter (view call allowed)
        address stakingAddr = address(c.stakingToken());

        // Read before-values from c
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));
        uint256 contractBalBefore = address(c).balance;

        // Make sure this contract has at least 'amount' staked in c by staking if necessary.
        // If balBefore < amount, attempt to stake the difference from this contract's token balance.
        if (balBefore < amount) {
            uint256 need = amount - balBefore;
            // require this contract has enough ERC20 tokens to stake
            // read token balance via view staticcall
            bytes memory data = abi.encodeWithSignature("balanceOf(address)", address(this));
            (bool okBal, bytes memory ret) = stakingAddr.staticcall(data);
            require(okBal && ret.length >= 32, "cannot read token balance");
            uint256 myBal;
            assembly { myBal := mload(add(ret, 32)) }
            require(myBal >= need, "test contract lacks tokens to stake");

            // Approve c to transfer tokens: top-level external call to token contract
            bytes memory approveCalldata = abi.encodeWithSignature("approve(address,uint256)", address(c), need);
            (bool okApprove, ) = stakingAddr.call(approveCalldata);
            require(okApprove, "approve failed");

            // Now stake the needed amount into c as a top-level call
            c.stakeFor(address(this), need);

            // update observed before-values to reflect post-stake state as new baseline
            totalBefore = c.totalSupply();
            balBefore = c.balanceOf(address(this));
            contractBalBefore = address(c).balance;
        }

        // Now perform the withdraw call on c as a top-level statement and capture whether it reverted
        bool reverted;
        try c.withdraw(amount, claim) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));
        uint256 contractBalAfter = address(c).balance;

        // If reverted: nothing should have changed. If succeeded: totalSupply and balance decrease by exactly amount,
        // and the contract's Ether balance change is consistent with the staking token transfer (i.e., staking token transfers do not change Ether balance).
        // Since stakingToken is an ERC20, withdrawing should not change c's ETH balance. So we assert that on success c's ETH balance is unchanged
        // and total/holder balances decreased by amount.
        assert(
            reverted
            ? (totalAfter == totalBefore && balAfter == balBefore && contractBalAfter == contractBalBefore)
            : (totalAfter == totalBefore - amount && balAfter == balBefore - amount && contractBalAfter == contractBalBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    IERC20 token;

    constructor(C _c) {
        c = _c;
        token = c.stakingToken();
    }

    // params: stake amount and an allowance source address (we use msg.sender of this contract when calling
    // staking functions since this contract is the caller). We require this contract hold enough tokens.
    function run(uint256 stakeAmount) public payable {
        require(stakeAmount > 0, "need positive stake");

        // ensure this test contract has enough tokens to stake
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(address(this));
        uint256 tokenBalanceBefore = token.balanceOf(address(this));

        // Approve c to pull tokens from this contract
        // Note: safeApprove may require current allowance 0; to be safe, first set to 0 then to stakeAmount
        // We call token.approve directly because IERC20 is visible; these are external calls that may revert.
        // If token doesn't allow approve pattern, the test will catch revert and fail to reach assert; that's acceptable.
        token.approve(address(c), 0);
        token.approve(address(c), stakeAmount);

        bool revertedStake = false;
        try c.stakeFor(address(this), stakeAmount) {
            revertedStake = false;
        } catch {
            revertedStake = true;
        }

        // Only attempt withdraw if stake didn't revert; record values after stake attempt
        uint256 totalAfterStake = c.totalSupply();
        uint256 balanceAfterStake = c.balanceOf(address(this));
        uint256 tokenBalanceAfterStake = token.balanceOf(address(this));

        bool revertedWithdraw = false;
        if (!revertedStake) {
            try c.withdraw(stakeAmount, false) {
                revertedWithdraw = false;
            } catch {
                revertedWithdraw = true;
            }
        }

        uint256 totalAfter = c.totalSupply();
        uint256 balanceAfter = c.balanceOf(address(this));
        uint256 tokenBalanceAfter = token.balanceOf(address(this));

        // General property asserted:
        // If stake succeeded and withdraw succeeded, then totalSupply and staker balance are restored to before values,
        // and this contract's token balance is restored to (or increased by) what it was before (i.e., the token was returned).
        // We also assert that if stake reverted then nothing changed in c's viewable balances.
        assert(
            (
                !revertedStake && !revertedWithdraw &&
                totalAfter == beforeTotal &&
                balanceAfter == beforeBalance &&
                tokenBalanceAfter >= tokenBalanceBefore
            ) || (
                revertedStake && totalAfterStake == beforeTotal && balanceAfterStake == beforeBalance && tokenBalanceAfterStake == tokenBalanceBefore
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
