    }

    // params: amount to stake/withdraw. The test contract must hold and approve at least this amount for c.
    function run(uint256 amt) public payable {
        require(amt > 0, "amt>0");

        // observe before values
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));
        uint256 tokBalBefore = token.balanceOf(address(this));

        // prepare approvals in top-level statements
        token.approve(address(c), 0);
        token.approve(address(c), amt);

        // perform stakeFor. This is a top-level state-changing call on c.
        bool stakeSucceeded = true;
        try c.stakeFor(address(this), amt) {
            stakeSucceeded = true;
        } catch {
            stakeSucceeded = false;
        }

        // read intermediate values unconditionally (view calls allowed anywhere)
        uint256 totalAfterStake = c.totalSupply();
        uint256 balAfterStake = c.balanceOf(address(this));
        uint256 tokBalAfterStake = token.balanceOf(address(this));

        // attempt withdraw only as a top-level call; record whether it reverts
        bool withdrawSucceeded = true;
        if (stakeSucceeded) {
            try c.withdraw(amt, false) {
                withdrawSucceeded = true;
            } catch {
                withdrawSucceeded = false;
            }
        } else {
            withdrawSucceeded = false;
        }

        // observe after everything
        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));
        uint256 tokBalAfter = token.balanceOf(address(this));

        // General property:
        // If both stakeFor and withdraw succeeded, c.totalSupply and c.balanceOf(this) return to their previous values,
        // and this contract's token balance does not decrease (it is restored or increased).
        // Otherwise, if stake failed then c's observed totals/balances after the failed stake must equal the before-values.
        assert(
            (
                stakeSucceeded && withdrawSucceeded &&
                totalAfter == totalBefore &&
                balAfter == balBefore &&
                tokBalAfter >= tokBalBefore
            ) || (
                !stakeSucceeded &&
                totalAfterStake == totalBefore &&
                balAfterStake == balBefore &&
                tokBalAfterStake == tokBalBefore
            )
        );
    }

    receive() external payable {}
}

