    // We take the staker address _for and an amount; msg.sender for c calls will be this contract.
    // The test tries to call stakeFor and records whether it reverted. It then checks a general relation:
    // If stakeFor succeeded then totalSupply and balanceOf(_for) are >= before + amt.
    // If stakeFor reverted then the low-level token transferFrom must have reverted (we can't observe token internals),
    // so we simply require that stakeFor reverted implies the call did revert (that's tautological). To make a
    // non-trivial property we check monotonicity: after a successful stakeFor, totalSupply and balanceOf(_for)
    // increased by at least amt.

    // Note: we must not call any non-public members of C. We only call stakeFor and the public views.

    function run(address _for, uint256 amt) public payable {
        require(amt > 0, "pre: amt>0");

