        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(_for);

        bool reverted;
        try c.stakeFor(_for, amt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterBalance = c.balanceOf(_for);

        // General rule:
        // If the call succeeded then totalSupply and balanceOf(_for) increased by at least amt.
        // If the call reverted then we cannot observe state change; still assert that reverted implies
        // the observed after values did not both increase by >= amt. This avoids trivial tautology assert(true).
        assert(
            (!reverted && afterTotal >= beforeTotal + amt && afterBalance >= beforeBalance + amt)
            || (reverted && !(afterTotal >= beforeTotal + amt && afterBalance >= beforeBalance + amt))
        );
    }

    receive() external payable {}
}

