contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: distributor must be msg.sender when calling notifyRewardAmount, so we take distributor as address
    // but per harness, msg.sender for calls from this contract is InvMutTest, and c was deployed with some distributor
    // We will attempt to call setRewardDistributor first as owner may differ; owner is deployer of C, not this test.
    // Instead we will assume reward token has been added by owner before; to be robust we add a new reward token via try/catch

    function run(address rewardToken, address distributor, uint256 amount) public payable {
        require(rewardToken != address(0) && distributor != address(0));

        // Record current rewardPerToken (if token unknown this call will revert; catch and treat as unknown)
        bool preReverted;
        uint256 beforeRPT;
        try c.rewardPerToken(rewardToken) returns (uint256 v) {
            preReverted = false;
            beforeRPT = v;
        } catch {
            preReverted = true;
            beforeRPT = 0;
        }

        // Try to set rewardDistributor to distributor if this contract is owner: may revert; ignore revert
        bool setDistReverted;
        try c.setRewardDistributor(distributor) {
            setDistReverted = false;
        } catch {
            setDistReverted = true;
        }

        // Ensure this contract has allowance and tokens is outside scope; calling notifyRewardAmount may revert if msg.sender != rewardDistributor
        // Call notifyRewardAmount as this contract (msg.sender will be this test) - record if it reverts
        bool notifyReverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            notifyReverted = false;
        } catch {
            notifyReverted = true;
        }

        // After attempt, read rewardPerToken again (if view reverts, treat as reverted)
        bool postReverted;
        uint256 afterRPT;
        try c.rewardPerToken(rewardToken) returns (uint256 v2) {
            postReverted = false;
            afterRPT = v2;
        } catch {
            postReverted = true;
            afterRPT = 0;
        }

        // General rule: if rewardPerToken was readable before and readable after, then it did not decrease.
        // Also, if notifyRewardAmount succeeded (did not revert), then post value must be >= before value.
        // We assert a single general property combining these: whenever both reads succeeded, afterRPT >= beforeRPT.
        assert(!(preReverted == false && postReverted == false) || (afterRPT >= beforeRPT));
    }

    receive() external payable {}
}

