    // (observed via rewardPeriodFinish) after the call must be >= the lastUpdateTime that was observed just before the call
    // (we observe lastUpdateTime indirectly by calling rewardPerToken which updates internal state on success; because rewardData.lastUpdateTime is not public,
    // we instead read rewardPerToken and rewardPeriodFinish before the call and rewardPeriodFinish after; the invariant enforced here is:
    // if notifyRewardAmount succeeds and both reads of rewardPeriodFinish succeed, then post_periodFinish >= pre_lastUpdateTime where
    // pre_lastUpdateTime is inferred as min(pre_periodFinish, block timestamp) but to keep it observable we assert post_periodFinish >= pre_periodFinish_read_before
    // which must hold because notifyRewardAmount sets periodFinish = block.timestamp + DURATION and lastUpdateTime = block.timestamp.

    function run(address rewardToken, uint256 amount) public payable {
        require(rewardToken != address(0));

        // Read periodFinish before the notify attempt. If the call reverts, we still capture that fact.
        bool preReverted;
        uint40 beforePeriodFinish;
        try c.rewardPeriodFinish(rewardToken) returns (uint40 v) {
            preReverted = false;
            beforePeriodFinish = v;
        } catch {
            preReverted = true;
            beforePeriodFinish = 0;
        }

        // Attempt to call notifyRewardAmount and record whether it reverted.
        bool notifyReverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            notifyReverted = false;
        } catch {
            notifyReverted = true;
        }

        // Read periodFinish after the notify attempt.
        bool postReverted;
        uint40 afterPeriodFinish;
        try c.rewardPeriodFinish(rewardToken) returns (uint40 v2) {
            postReverted = false;
            afterPeriodFinish = v2;
        } catch {
            postReverted = true;
            afterPeriodFinish = 0;
        }

        // General rule: if notifyRewardAmount succeeded and both reads succeeded, then afterPeriodFinish >= beforePeriodFinish.
        // This captures that notifyRewardAmount cannot set periodFinish to a value before the previously observed periodFinish (it sets to now+DURATION).
        assert(!(notifyReverted == false && preReverted == false && postReverted == false) || (afterPeriodFinish >= beforePeriodFinish));
    }

    receive() external payable {}
}

