contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: distributor must match c.rewardDistributor(); rewardToken must have been added via addReward;
    // amount must be > 0 and this contract must hold at least `amount` of the reward token beforehand.
    function run(address distributor, address rewardToken, uint256 amount) public payable {
        require(amount > 0);

        // Precondition: caller of notifyRewardAmount must be the rewardDistributor. We'll simulate by
        // having this test contract call c.setRewardDistributor if the owner allows it. However setRewardDistributor
        // is onlyOwner; since the checker deploys c fresh, InvMutTest is the deployer of c, so it is the owner.
        // So we can set rewardDistributor to the provided distributor and then set it back to this contract
        // by calling setRewardDistributor(address(this)). To avoid relying on the previous owner, just set
        // reward distributor to address(this) now (we are owner because we deployed c in the harness condition).

        // Make sure rewardToken is known: call addReward(rewardToken) as owner (this contract is owner)
        c.addReward(rewardToken);

        // Set this contract as the rewardDistributor so we can call notifyRewardAmount
        c.setRewardDistributor(address(this));

        // Record previous periodFinish and token balance of c
        uint40 prevFinish = c.rewardPeriodFinish(rewardToken);
        uint256 beforeBalance = IERC20(rewardToken).balanceOf(address(c));

        // Transfer `amount` of rewardToken from msg.sender of this run call to this test contract, if needed.
        // We cannot move tokens from external accounts here, so require that this test contract already has enough tokens.
        // The check below ensures safety in case harness provides tokens to this contract before calling run.
        require(IERC20(rewardToken).balanceOf(address(this)) >= amount, "must fund test with reward tokens");

        // Approve c to pull the tokens
        IERC20(rewardToken).approve(address(c), amount);

        // Now call notifyRewardAmount as the configured distributor (this contract)
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call: if it did not revert, periodFinish must have increased (strictly > prevFinish)
        // and the contract's token balance must equal beforeBalance + amount.
        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterBalance = IERC20(rewardToken).balanceOf(address(c));

        assert(reverted || (afterFinish > prevFinish && afterBalance == beforeBalance + amount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test that stakeFor(_for, amount) when amount>0 either reverts or increments totalSupply and balanceOf(_for) by amount.
    // Params: forAddr - address to stake for; amount - stake amount; callerMustHave - this contract must hold at least `amount` of stakingToken beforehand.
    function run(address forAddr, uint256 amount) public payable {
        require(amount > 0);

        // Read before-values via public getters
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(forAddr);

        // Ensure this test contract has approved c to pull staking tokens and has sufficient balance.
        // We cannot call IERC20 here directly (not allowed to redeclare), so rely on the caller having pre-funded and approved off-chain.
        // Attempt the stakeFor call as a top-level state-changing call and capture whether it reverts.
        bool reverted;
        try c.stakeFor(forAddr, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint256 afterTotal = c.totalSupply();
        uint256 afterBalance = c.balanceOf(forAddr);

        // General invariant: either the call reverted, or totalSupply and the beneficiary balance each increased by exactly amount
        assert(reverted || (afterTotal == beforeTotal + amount && afterBalance == beforeBalance + amount));
    }

    receive() external payable {}
}

